input.new_string:
// RunDue attempts every delivery that is due and returns how many attempts it made. An answer with a 2xx status succeeds
// a delivery. Any other answer, or none, is a failed attempt: the delivery is tried again after retryDelays, and fails for
// good after maxAttempts attempts. A 410 Gone fails it for good at once and disables its endpoint. The error reports
// failure emails that could not be sent.
func (s *Service) RunDue(ctx context.Context) (int, error) {
	n := 0
	var mailErrs []error
	for _, d := range s.store.DueDeliveries(s.clock.Now()) {
		if err := ctx.Err(); err != nil {
			return n, errors.Join(err, errors.Join(mailErrs...))
		}
		attempted, err := s.deliver(ctx, d)
		if attempted {
			n++
		}
		if err != nil {
			mailErrs = append(mailErrs, err)
		}
	}
	return n, errors.Join(mailErrs...)
}

