func TestRetrySchedule(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep := newEndpoint(t, e, e.Acme, "https://hooks.acme.example/down", "*")
	owner2, _ := e.AddMember(e.Acme, "second@acme.example", store.RoleOwner)
	_, _ = e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusBadGateway, nil }
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	for attempt := 1; attempt <= 7; attempt++ {
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("attempt %d: RunDue = %d, %v", attempt, n, err)
		}
		d := onlyDelivery(t, e, ep)
		if d.Attempts != attempt || d.ResponseStatus != http.StatusBadGateway || d.Error == "" || d.LastAttemptAt == nil {
			t.Fatalf("attempt %d: delivery = %+v", attempt, d)
		}
		if attempt == 7 {
			if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
				t.Fatalf("after the 7th attempt: delivery = %+v, want failed with no next attempt", d)
			}
			break
		}
		if d.Status != store.DeliveryPending {
			t.Fatalf("attempt %d: status %s, want pending", attempt, d.Status)
		}
		wait := retryDelays[attempt-1]
		if d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(e.Clock.Now().Add(wait)) {
			t.Fatalf("attempt %d: next attempt %v, want %v later", attempt, d.NextAttemptAt, wait)
		}
		e.Clock.Advance(wait - time.Second)
		if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
			t.Fatalf("attempt %d: retried a second early", attempt+1)
		}
		e.Clock.Advance(time.Second)
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a delivery that failed for good was sent again: %d", n)
	}
	if got := len(e.HTTP.Requests()); got != 7 {
		t.Fatalf("requests = %d, want 7", got)
	}
	msgs := e.Mail.Messages()
	if len(msgs) != 2 {
		t.Fatalf("emails = %+v, want one to each owner", msgs)
	}
	to := map[string]bool{msgs[0].To: true, msgs[1].To: true}
	if !to["owner@acme.example"] || !to[owner2.Email] {
		t.Fatalf("emailed %v", to)
	}
	if want := "Webhook endpoint failing: https://hooks.acme.example/down"; msgs[0].Subject != want {
		t.Fatalf("subject %q, want %q", msgs[0].Subject, want)
	}
	if got, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID); got.FailureMailedAt == nil || !got.Enabled {
		t.Fatalf("endpoint = %+v, want mailed and still enabled", got)
	}
}

